"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"

import { type NavUserLabels, NavUser } from "@/components/shell/nav-user"
import { type WorkspaceSwitcherLabels, WorkspaceSwitcher } from "@/components/shell/workspace-switcher"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@/components/ui/sidebar"
import { navigation } from "@/lib/nav"
import { mergeLabels } from "@/lib/labels"

export type AppSidebarLabels = {
  navigation: string
  /** Accessible name of the pending-count badge, e.g. "12 pending". */
  pending: (count: string) => string
  /** Overrides forwarded to the workspace switcher. */
  workspaceSwitcher?: Partial<WorkspaceSwitcherLabels>
  /** Overrides forwarded to the user menu. */
  navUser?: Partial<NavUserLabels>
}

export const defaultAppSidebarLabels: AppSidebarLabels = {
  navigation: "Main navigation",
  pending: (count) => `${count} pending`,
}

function isActive(pathname: string, href: string) {
  return href === "/" ? pathname === "/" : pathname === href || pathname.startsWith(`${href}/`)
}

export function AppSidebar({
  labels,
  ...props
}: React.ComponentProps<typeof Sidebar> & { labels?: Partial<AppSidebarLabels> }) {
  const pathname = usePathname()
  const t = mergeLabels(defaultAppSidebarLabels, labels)

  return (
    <Sidebar aria-label={t.navigation} {...props}>
      <SidebarHeader>
        <WorkspaceSwitcher labels={t.workspaceSwitcher} />
      </SidebarHeader>
      <SidebarContent>
        {navigation.map((group) => (
          <SidebarGroup key={group.label}>
            <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {group.items.map((item) => {
                  const active = isActive(pathname, item.href)
                  return (
                    <SidebarMenuItem key={item.href}>
                      <SidebarMenuButton asChild isActive={active} tooltip={item.title}>
                        <Link href={item.href} aria-current={active ? "page" : undefined}>
                          <item.icon aria-hidden />
                          <span>{item.title}</span>
                        </Link>
                      </SidebarMenuButton>
                      {item.badge ? (
                        <SidebarMenuBadge aria-label={t.pending(item.badge)}>{item.badge}</SidebarMenuBadge>
                      ) : null}
                    </SidebarMenuItem>
                  )
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Alex Morgan", email: "alex@example.com" }} labels={t.navUser} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  )
}

"use client"

import { Check, ChevronsUpDown } from "lucide-react"
import * as React from "react"

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar"
import { mergeLabels } from "@/lib/labels"

export type WorkspaceSwitcherLabels = {
  environment: string
  current: string
}

export const defaultWorkspaceSwitcherLabels: WorkspaceSwitcherLabels = {
  environment: "Environment",
  current: "Current",
}

const environments = ["Production", "Staging"]

export function WorkspaceSwitcher({
  name = "Acme Rentals",
  labels,
}: {
  name?: string
  labels?: Partial<WorkspaceSwitcherLabels>
}) {
  const t = mergeLabels(defaultWorkspaceSwitcherLabels, labels)
  const { isMobile } = useSidebar()
  const [current, setCurrent] = React.useState(0)

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <SidebarMenuButton size="lg" className="data-[state=open]:bg-sidebar-accent">
              <div
                aria-hidden
                className="flex aspect-square size-8 items-center justify-center rounded-md bg-primary font-semibold text-primary-foreground"
              >
                {name[0]}
              </div>
              <div className="grid flex-1 text-left leading-tight">
                <span className="truncate font-medium">{name}</span>
                <span className="truncate text-xs text-muted-foreground">{environments[current]}</span>
              </div>
              <ChevronsUpDown className="ml-auto" aria-hidden />
            </SidebarMenuButton>
          </DropdownMenuTrigger>
          <DropdownMenuContent className="min-w-56" align="start" side={isMobile ? "bottom" : "right"} sideOffset={4}>
            <DropdownMenuLabel className="text-xs text-muted-foreground">{t.environment}</DropdownMenuLabel>
            {environments.map((env, i) => (
              <DropdownMenuItem key={env} onSelect={() => setCurrent(i)}>
                <span className="flex-1">{env}</span>
                {i === current ? <Check aria-label={t.current} /> : null}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
    </SidebarMenu>
  )
}

"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { Fragment } from "react"

import { type CommandMenuLabels, CommandMenu } from "@/components/shell/command-menu"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Separator } from "@/components/ui/separator"
import { SidebarTrigger } from "@/components/ui/sidebar"
import { segmentLabels } from "@/lib/nav"
import { mergeLabels } from "@/lib/labels"

export type SiteHeaderLabels = {
  /** First breadcrumb, the root page. */
  overview: string
  /** Overrides forwarded to the command menu. */
  commandMenu?: Partial<CommandMenuLabels>
}

export const defaultSiteHeaderLabels: SiteHeaderLabels = { overview: "Overview" }

export function SiteHeader({ labels }: { labels?: Partial<SiteHeaderLabels> }) {
  const t = mergeLabels(defaultSiteHeaderLabels, labels)
  const pathname = usePathname()
  const segments = pathname.split("/").filter(Boolean)
  const crumbs = [
    { href: "/", label: t.overview },
    ...segments.map((s, i) => ({
      href: `/${segments.slice(0, i + 1).join("/")}`,
      label: segmentLabels[s] ?? s,
    })),
  ]

  return (
    <header className="sticky top-0 z-10 flex h-12 shrink-0 items-center gap-2 border-b bg-background/90 px-4 backdrop-blur md:rounded-t-xl">
      <SidebarTrigger className="-ml-1" />
      <Separator orientation="vertical" className="mr-1 data-[orientation=vertical]:h-4" />
      <Breadcrumb>
        <BreadcrumbList>
          {crumbs.map((c, i) => {
            const last = i === crumbs.length - 1
            return (
              <Fragment key={c.href}>
                {i > 0 ? <BreadcrumbSeparator className="hidden md:block" /> : null}
                <BreadcrumbItem className={last ? undefined : "hidden md:inline-flex"}>
                  {last ? (
                    <BreadcrumbPage>{c.label}</BreadcrumbPage>
                  ) : (
                    <BreadcrumbLink asChild>
                      <Link href={c.href}>{c.label}</Link>
                    </BreadcrumbLink>
                  )}
                </BreadcrumbItem>
              </Fragment>
            )
          })}
        </BreadcrumbList>
      </Breadcrumb>
      <div className="ml-auto flex items-center gap-2">
        <CommandMenu labels={t.commandMenu} />
      </div>
    </header>
  )
}

import { mergeLabels } from "@/lib/labels"

export type SkipLinkLabels = { skip: string }

export const defaultSkipLinkLabels: SkipLinkLabels = { skip: "Skip to content" }

/** Keyboard-only link to the element with `id="main"`. */
export function SkipLink({ labels }: { labels?: Partial<SkipLinkLabels> }) {
  const t = mergeLabels(defaultSkipLinkLabels, labels)
  return (
    <a
      href="#main"
      className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-50 focus:rounded-md focus:bg-background focus:px-3 focus:py-2 focus:ring-2 focus:ring-ring"
    >
      {t.skip}
    </a>
  )
}

import { cn } from "@/lib/utils"

export function PageHeader({
  title,
  description,
  actions,
  className,
}: {
  title: string
  description?: string
  actions?: React.ReactNode
  className?: string
}) {
  return (
    <div className={cn("flex flex-wrap items-end justify-between gap-4", className)}>
      <div className="space-y-1">
        <h1 className="text-xl font-semibold tracking-tight">{title}</h1>
        {description ? <p className="text-muted-foreground">{description}</p> : null}
      </div>
      {actions ? <div className="flex items-center gap-2">{actions}</div> : null}
    </div>
  )
}

export function PageContainer({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <div className={cn("mx-auto flex w-full max-w-7xl flex-1 flex-col gap-6 p-4 md:p-6", className)}>{children}</div>
  )
}

"use client"

import { ThemeProvider as NextThemesProvider } from "next-themes"

export function ThemeProvider(props: React.ComponentProps<typeof NextThemesProvider>) {
  return <NextThemesProvider {...props} />
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768
const query = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`

function subscribe(onChange: () => void) {
  const mql = window.matchMedia(query)
  mql.addEventListener("change", onChange)
  return () => mql.removeEventListener("change", onChange)
}

export function useIsMobile() {
  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  )
}

import {
  LayoutDashboard,
  Package,
  Settings,
  Users,
  type LucideIcon,
} from "lucide-react"

export type NavItem = { title: string; href: string; icon: LucideIcon; badge?: string }
export type NavGroup = { label: string; items: NavItem[] }

export const navigation: NavGroup[] = [
  {
    label: "Workspace",
    items: [
      { title: "Overview", href: "/", icon: LayoutDashboard },
      { title: "Orders", href: "/orders", icon: Package, badge: "12" },
      { title: "Customers", href: "/customers", icon: Users },
    ],
  },
  {
    label: "Configuration",
    items: [{ title: "Settings", href: "/settings", icon: Settings }],
  },
]

/** Human labels for path segments used by the breadcrumbs. */
export const segmentLabels: Record<string, string> = {
  orders: "Orders",
  new: "New order",
  customers: "Customers",
  settings: "Settings",
}

import { AppSidebar } from "@/components/shell/app-sidebar"
import { SiteHeader } from "@/components/shell/site-header"
import { SkipLink } from "@/components/shell/skip-link"
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar"

// The shell stays static (prerendered). Reading the sidebar cookie here would make every
// route dynamic under cacheComponents, so the sidebar always starts open.
export default function AppLayout({ children }: LayoutProps<"/">) {
  return (
    <SidebarProvider>
      <SkipLink />
      <AppSidebar variant="inset" collapsible="icon" />
      <SidebarInset>
        <SiteHeader />
        <div id="main" className="flex flex-1 flex-col">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

import type { Metadata } from "next"
import { Inter, Geist_Mono } from "next/font/google"

import { ThemeProvider } from "@/components/shell/theme-provider"
import { Toaster } from "@/components/ui/sonner"
import { TooltipProvider } from "@/components/ui/tooltip"
import "./globals.css"

const inter = Inter({ variable: "--font-inter", subsets: ["latin"] })
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] })

export const metadata: Metadata = {
  title: { default: "Back office", template: "%s · Back office" },
  description: "Back office reference built on shadcn/ui.",
}

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" suppressHydrationWarning className={`${inter.variable} ${geistMono.variable} antialiased`}>
      <body>
        <ThemeProvider attribute="class" defaultTheme="system" enableSystem disableTransitionOnChange>
          <TooltipProvider delayDuration={300}>{children}</TooltipProvider>
          <Toaster position="bottom-right" />
        </ThemeProvider>
      </body>
    </html>
  )
}

/** Merge partial label overrides over the defaults; an explicit `undefined` keeps the default. */
export function mergeLabels<T extends object>(defaults: T, overrides?: Partial<T>): T {
  const merged = { ...defaults }
  for (const key of Object.keys(overrides ?? {}) as (keyof T)[]) {
    const value = overrides?.[key]
    if (value !== undefined) merged[key] = value as T[keyof T]
  }
  return merged
}
